insert into public.content (id, kind, published, data) values ('home', 'pages', true, '{"id":"home","kind":"pages","title":"We engineer\nthe experience.","description":"Scène, structure, image, son et lumière : EVENTHEMES fournit, installe et exploite les solutions techniques de vos événements au Maroc.","published":true,"subtitle":"EVENT TECHNICAL PRODUCTION · MAROC","image":"https://images.unsplash.com/photo-1563841930606-67e2bce48b78?auto=format&fit=crop&w=2000&q=85","demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('about', 'pages', true, '{"id":"about","kind":"pages","title":"La technique au service\nde vos événements.","description":"EVENTHEMES est spécialisée dans les solutions techniques et audiovisuelles pour événements de toutes tailles. Nous intervenons dans la fourniture, la location, l’installation et l’exploitation des équipements nécessaires aux événements professionnels et privés.","published":true,"subtitle":"À PROPOS D’EVENTHEMES","image":"https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1400&q=85","demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('values', 'pages', true, '{"id":"values","kind":"pages","title":"Puissance technique.\nExcellence professionnelle.","description":"Trois valeurs guident chaque projet : la puissance technique, l’excellence professionnelle et l’innovation audiovisuelle. Une préparation rigoureuse, pour une technique qui sert l’événement sans jamais s’imposer.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('contact', 'pages', true, '{"id":"contact","kind":"pages","title":"Parlons de votre\nprochain événement.","description":"Un lieu, une date, un format ? Décrivez-nous votre projet : notre équipe revient vers vous pour préparer une offre adaptée.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('services-page', 'pages', true, '{"id":"services-page","kind":"pages","title":"Nos expertises\ntechniques.","description":"Scènes, structures, écrans, son, lumière et régie : des prestations complètes ou à la carte, de l’étude technique au démontage.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('location-page', 'pages', true, '{"id":"location-page","kind":"pages","title":"Le parc\nmatériel.","description":"Parcourez nos équipements par catégorie et ajoutez-les à votre demande de devis. La disponibilité et le tarif final sont confirmés par notre équipe selon la date, la quantité, la durée et le lieu.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('projects-page', 'pages', true, '{"id":"projects-page","kind":"pages","title":"Nos\nréalisations.","description":"Galas, événements corporate, concerts, festivals, conférences : nos projets, classés par type d’événement.","published":true,"demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('scenes', 'services', true, '{"id":"scenes","kind":"services","title":"Scènes & podiums","description":"Scènes modulaires, podiums et plateformes : une base stable, dimensionnée pour votre lieu et votre programme.","published":true,"category":"Scène","image":"https://images.unsplash.com/photo-1504680177321-2e6a879aac86?auto=format&fit=crop&w=2000&q=85","pricing":"request","demo":false,"available":true}'::jsonb) on conflict (id) do nothing;
